    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Quarto compartilhado (tipo twin, com outro estudante do mesmo sexo, mínimo 12 semanas para tarifa promocional). Banheiro compartilhado (banheiro privativo pode ser solicitado, sujeito a disponibilidade). Sem plano de refeições incluído — acomodação self-catering. Inclui: Wi-Fi, máquina de lavar, roupa de cama, toalhas e transporte de chegada do aeroporto. Não inclui: refeições.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 30/semana (28/jun a 29/ago); Desconto de baixa temporada: EUR 30/semana (3/jan a 28/fev e 1/nov a 31/dez); Suplemento banheiro privativo: EUR 70/semana; Noite extra: EUR 70; Depósito caução (reembolsável): EUR 100; Outro suplemento: EUR 10.5.</p><p>Ajuste sazonal da acomodação, por semana: alta temporada 28/jun a 29/ago +€30; baixa temporada 3/jan a 28/fev e 1/nov a 31/dez -€30; média temporada 1/mar a 27/jun e 30/ago a 31/out sem ajuste. O ajuste não se aplica a reservas de 12+ semanas. Taxa obrigatória: Eco Tax (18+) €10,50 por semana, máximo €22,50 por estadia. Transfer de chegada com check-in €50 (obrigatório) e transfer de saída €40 (opcional); pessoa adicional no mesmo transfer €10. Alteração de reserva €30. Opcionais por semana: banheiro privativo €70 (mediante solicitação, em quarto individual); seguro €17. Noite extra €70 por noite. Depósito caução reembolsável de €100 em dinheiro, recolhido no primeiro dia de aula para quem fica em residência BELS e devolvido no último dia se não houver danos. Semanas calculadas em estadias de 7 noites (check-in sábado/domingo, entrada 15:00 e saída 10:00); noites extras para chegada antecipada ou saída tardia são cobradas à parte. Fonte: BELS Malta Price List 2026 (atualização fev/2026).</p>','["Residência self-catering nas North Residences ou Westend, à beira-mar em St. Paul''s Bay, a 20 min a pé ou 5 min de ônibus da escola; cozinha totalmente equipada, máquina de lavar, TV e Wi-Fi; áreas comuns para socializar; limpeza semanal; opção mais econômica entre as residências da BELS; suporte 24/7 da equipe da escola.", "Ideal para estudantes de longa duração com orçamento reduzido"]'::jsonb,'["Menos indicado para quem quer mais conforto e privacidade"]'::jsonb);
